import {$,clear,el} from './literary-core-dom.js'; import {events} from './event-bus.js'; import {router} from './literary-core-router.js'; import {loadJson} from './literary-core-config-loader.js';
export async function installCommandPalette(){const dialog=$('#command-dialog'),input=$('#command-filter'),results=$('#command-results');const commands=await loadJson('json/commands.json');function render(q=''){clear(results);commands.filter(x=>x.label.toLowerCase().includes(q.toLowerCase())).forEach(c=>results.append(el('button',{type:'button',text:c.label,onClick:()=>{dialog.close();router.go(c.route);}})));} input?.addEventListener('input',()=>render(input.value));$('#command-button')?.addEventListener('click',()=>{render();dialog.showModal();input.focus();});events.on('command:palette',()=>{$('#command-button')?.click();});}
